from pathlib import Path
R=Path(unreal.Paths.project_dir()).resolve();O=R/'Saved/GlumandaV11';E=unreal.get_editor_subsystem(unreal.UnrealEditorSubsystem);assert not E.get_game_world() and not unreal.EditorLoadingAndSavingUtils.get_dirty_map_packages() and not unreal.EditorLoadingAndSavingUtils.get_dirty_content_packages();s=unreal.load_asset('/Game/Data/Creatures/DA_Zunderlauf');assert str(s.get_display_name())=='Zunderlauf' and str(s.get_internal_id())=='Zunderlauf';identity='CreatureSpecies:'+str(s.get_internal_id());s.set_editor_property('display_name',unreal.Text('Glumanda'));assert 'CreatureSpecies:'+str(s.get_internal_id())==identity and str(s.get_internal_id())=='Zunderlauf';assert unreal.EditorAssetLibrary.save_loaded_asset(s,False);(O/'NameChange.json').write_text(json.dumps({'old':'Zunderlauf','new':str(s.get_display_name()),'asset':s.get_path_name(),'stable_identity':identity,'other_fields_changed':False},indent=2));print('GLUMANDA_DISPLAY_NAME_ONLY_CHANGED')
